    onChange,
    selectsRange,
    startDate,
    endDate,
    selectsMultiple,
    selectedDates,
    minTime,
    swapRange,
  } = this.props;

  if (
    !isEqual(this.props.selected, changedDate) ||
    this.props.allowSameDay ||
    selectsRange ||
    selectsMultiple
  ) {
    if (changedDate !== null) {
      // Preserve previously selected time if only date is currently being changed
